namespace Aegis.Cafeteria.PersistenceTests;
using Aegis.Cafeteria.Application.Abstractions; using Aegis.Cafeteria.Application.Accounts; using Aegis.Cafeteria.Domain.Accounts; using Aegis.Cafeteria.Domain.Customers; using Aegis.Cafeteria.Domain.Orders; using Aegis.Cafeteria.Infrastructure.Configuration; using Aegis.Cafeteria.Infrastructure.Persistence; using Aegis.Cafeteria.Infrastructure.Persistence.Models; using Microsoft.EntityFrameworkCore; using Microsoft.Extensions.Logging.Abstractions;
public sealed class CustomerAccountQueryTests
{
 [Fact] public async Task GetAsync_UsesSeparateCreditAndSubsidyPolicyAndLocalTransactions(){var file=SqliteTestDatabase.CreatePath("account");try{var (factory,store)=await Setup(file);var customer=new Customer(7,"Test Customer",[1,2,3],true,2000m);await store.SaveCustomerAsync(customer);await AddPolicy(factory,800m,600m);var at=new DateTimeOffset(2026,8,10,12,0,0,TimeSpan.Zero);var order=new Order(Guid.NewGuid(),7,at.AddMinutes(-2));order.AddItem(new OrderItem(1,"Lunch",650m,1));order.Submit(at.AddMinutes(-1));order.Complete([new OrderPayment(Guid.NewGuid(),PaymentMethod.CafeteriaAccount,650m,at)],at,"cashier","TEST-01");await store.SaveOrderAsync(order);var q=Query(factory,store,20);var result=Assert.IsType<Aegis.Cafeteria.Application.Reporting.CustomerAccountView>(await q.GetAsync(7,2026,8));Assert.Equal(16_000m,result.FinancialStatus.CreditLimit);Assert.Equal(12_000m,result.Period.SubsidyAllocation);Assert.Equal(4_000m,result.Period.EmployeeFundedAllocation);Assert.True(result.Funding.IsAuthoritative);Assert.Contains(result.Transactions,x=>x.Kind=="Purchase"&&x.Amount==650m);}finally{SqliteTestDatabase.Delete(file);}}
 [Fact] public async Task GetAsync_OutstandingBalance_ExcludesPayrollDeduction(){var file=SqliteTestDatabase.CreatePath("outstanding-net-payroll");try{var (factory,store)=await Setup(file);var customer=new Customer(8,"Payroll Customer",null,true,2000m);await store.SaveCustomerAsync(customer);await AddPolicy(factory,800m,600m);var at=new DateTimeOffset(2026,8,10,12,0,0,TimeSpan.Zero);var order=new Order(Guid.NewGuid(),8,at.AddMinutes(-2));order.AddItem(new OrderItem(1,"Lunch",13_500m,1));order.Submit(at.AddMinutes(-1));order.Complete([new OrderPayment(Guid.NewGuid(),PaymentMethod.CafeteriaAccount,13_000m,at),new OrderPayment(Guid.NewGuid(),PaymentMethod.Credit,500m,at)],at,"cashier","TEST-01");await store.SaveOrderAsync(order);var result=Assert.IsType<Aegis.Cafeteria.Application.Reporting.CustomerAccountView>(await Query(factory,store,20).GetAsync(8,2026,8));Assert.Equal(4_000m,result.Period.EmployeeFundedAllocation);Assert.Equal(3_000m,result.FinancialStatus.NonSubsidyAmountRemaining);Assert.Equal(500m,result.FinancialStatus.CurrentCreditSaleDebt);Assert.Equal(500m,result.FinancialStatus.EmployeeAmountDue);}finally{SqliteTestDatabase.Delete(file);}}
 [Fact] public async Task GetAsync_MissingPolicy_ReturnsTemporaryZeroWithoutPersistingAllocation(){var file=SqliteTestDatabase.CreatePath("missing-policy");try{var (factory,store)=await Setup(file);await store.SaveCustomerAsync(new Customer(9,"No Policy",null,true,0m));var result=await Query(factory,store,20).GetAsync(9,2026,8);Assert.NotNull(result);Assert.Equal(0m,result!.FinancialStatus.CreditLimit);Assert.False(result.Funding!.IsAuthoritative);await using var db=factory.CreateDbContext();Assert.Empty(await db.MonthlyCreditAllocations.ToListAsync());}finally{SqliteTestDatabase.Delete(file);}}
 [Fact] public async Task GetTransactionsAsync_PreviousMonth_DoesNotCreateAllocation(){var file=SqliteTestDatabase.CreatePath("history");try{var (factory,store)=await Setup(file);await store.SaveCustomerAsync(new Customer(77,"History",null,true,0m));var at=new DateTimeOffset(2026,7,15,12,0,0,TimeSpan.Zero);var order=new Order(Guid.NewGuid(),77,at.AddMinutes(-2));order.AddItem(new OrderItem(1,"Lunch",650m,1));order.Submit(at.AddMinutes(-1));order.Complete([new OrderPayment(Guid.NewGuid(),PaymentMethod.Cash,650m,at)],at,"cashier","TEST-01");await store.SaveOrderAsync(order);var history=await Query(factory,store,20).GetTransactionsAsync(77,2026,7);Assert.Contains(history,x=>x.CashAmount==650m);await using var db=factory.CreateDbContext();Assert.Empty(await db.MonthlyCreditAllocations.ToListAsync());}finally{SqliteTestDatabase.Delete(file);}}
 private static async Task<(LocalDbContextFactory,EfCafeteriaPersistenceStore)> Setup(string file){var factory=new LocalDbContextFactory(DbContextOptionsFactory.CreateLocal(new CafeteriaPersistenceOptions{LocalSqliteConnectionString=$"Data Source={file}",TerminalId="TEST-01"}));await using(var db=factory.CreateDbContext())await db.Database.EnsureCreatedAsync();return(factory,new EfCafeteriaPersistenceStore(new LocalPersistenceStore(factory,NullLogger<LocalPersistenceStore>.Instance)));}
 private static async Task AddPolicy(LocalDbContextFactory factory,decimal creditPrice,decimal subsidyCost){await using var db=factory.CreateDbContext();db.CafeteriaRatePolicies.Add(new CafeteriaRatePolicyRow{Id=1,CreditLimitLunchItemCode="FFP00",CreditLimitPrice=creditPrice,SubsidyLunchItemCode="FFP00",SubsidyCost=subsidyCost,RefreshedAt=DateTimeOffset.UtcNow});await db.SaveChangesAsync();}
 private static EfCustomerAccountQuery Query(LocalDbContextFactory factory,EfCafeteriaPersistenceStore store,int days)=>new(factory,new MonthlyCreditAllocationService(new Days(days),new EfCafeteriaRatePolicyProvider(factory),store),new EfExternalPublicationStatusProvider(factory,new CafeteriaServicesOptions{Enabled=true}));
 private sealed class Days(int value):IWorkingDayProvider{public Task<int> GetWorkingDaysAsync(int year,int month,CancellationToken cancellationToken=default)=>Task.FromResult(value);}
}
